import { bestEfforts } from './progress-model.js';
import { MEASURES,metricValue,metricHeadline,kilometreSplits,distanceAxis } from './activity-analysis.js';
export const visualTime=s=>{if(!Number.isFinite(s))return '—';const n=Math.round(s);return n>=3600?Math.floor(n/3600)+':'+String(Math.floor(n%3600/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0'):Math.floor(n/60)+':'+String(n%60).padStart(2,'0');};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function metricText(value,kind){return !Number.isFinite(value)?'—':kind==='pace'?visualTime(value):Math.round(value).toString();}
export function metricSvg(c,kind,cursor=null,selection=null){
 if(!c)return '';
 const unit=MEASURES[kind].unit,v=cursor?metricValue(cursor,kind):null;
 const step=c.axis==='distance'?c.end>10000?5000:c.end>5000?2000:1000:null,ticks=step?Array.from({length:Math.floor(c.end/step)},(_,i)=>(i+1)*step):[0,c.end/3,c.end*2/3,c.end];
 return `<svg viewBox="0 0 ${c.width} 265" role="img" aria-label="${MEASURES[kind].label} by ${c.axis}. ${c.terrain?'Muted area shows terrain on its own elevation scale. ':''}Use the chart arrow keys to inspect exact recorded values."><defs><clipPath id="metric-clip"><rect x="${c.left}" y="${c.top}" width="${c.right-c.left}" height="${c.bottom-c.top}"/></clipPath><linearGradient id="metric-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--av-signal)" stop-opacity=".6"/><stop offset="1" stop-color="var(--av-signal)" stop-opacity=".04"/></linearGradient></defs>${[0,.5,1].map(f=>{const value=c.min+(c.max-c.min)*f,y=c.y(value);return `<path class="av-grid" d="M${c.left} ${y}H${c.right}"/><text x="${c.left-12}" y="${y+4}" text-anchor="end">${metricText(value,kind)}</text>`;}).join('')}${ticks.map(t=>`<path class="av-grid av-grid-vertical" d="M${c.left+t/c.end*(c.right-c.left)} ${c.top}V${c.bottom}"/><text x="${c.left+t/c.end*(c.right-c.left)}" y="250" text-anchor="middle">${c.axis==='distance'?(t/1000)+' km':visualTime(t)}</text>`).join('')}<g clip-path="url(#metric-clip)"><path class="av-terrain" d="${c.terrain}"/><path class="av-area" d="${c.area}"/>${selection?`<rect class="av-selection" x="${c.timeX(selection.start)}" y="${c.top}" width="${Math.max(1,c.timeX(selection.end)-c.timeX(selection.start))}" height="${c.bottom-c.top}"/>`:""}<path class="av-line" d="${c.d}"/></g><text x="${c.left}" y="12">${unit}</text><g class="chart-live-cursor">${Number.isFinite(v)&&v>=c.min&&v<=c.max?`<path class="chart-cursor-line" d="M${c.x(cursor)} ${c.top}V${c.bottom}"/><circle class="chart-cursor-dot" cx="${c.x(cursor)}" cy="${c.y(v)}" r="5"/>`:''}</g></svg>`;
}
export function metricSummary(activity,kind){
 const rows=activity.records,values=rows.map(r=>metricValue(r,kind)).filter(Number.isFinite);if(!values.length)return '';
 const source=kind==='pace'?activity.distance>=10?(activity.timer??activity.running??activity.moving)/activity.distance*1000:null:kind==='heart'?activity.hr:kind==='cadence'?activity.cadence:null;
 const min=values.reduce((a,b)=>Math.min(a,b),Infinity),max=values.reduce((a,b)=>Math.max(a,b),-Infinity),splits=kilometreSplits(activity).filter(s=>s.complete&&s.distanceM>=999);
 let insight='';
 if(kind==='pace'&&splits.length>=2){const change=splits.at(-1).paceSPerKm-splits[0].paceSPerKm;insight=Math.abs(change)<2?'Your opening and closing kilometres were evenly paced.':`Your closing kilometre was ${visualTime(Math.abs(change))} /km ${change<0?'quicker':'slower'} than your opening.`;}
 if(kind==='heart'&&splits.length>=2&&splits[0].hrBpm!==null&&splits.at(-1).hrBpm!==null)insight=`Your first kilometre averaged ${Math.round(splits[0].hrBpm)} bpm; your final full kilometre averaged ${Math.round(splits.at(-1).hrBpm)} bpm.`;
 if(kind==='power')insight=`Your recorded running power peaked at ${Math.round(max)} watts.`;
 if(kind==='cadence')insight=`Your recorded cadence ranged from ${Math.round(min)} to ${Math.round(max)} steps per minute.`;
 if(kind==='elevation')insight=`The route ranged from ${Math.round(min)} to ${Math.round(max)} metres${Number.isFinite(activity.elevationGain)?`, with ${Math.round(activity.elevationGain)} m of recorded climbing`:''}.`;
 return `<div class="av-summary"><dl>${Number.isFinite(source)?`<div><dt>${kind==='pace'?'Timer pace':'Average'}</dt><dd>${metricText(source,kind)} <small>${MEASURES[kind].unit}</small></dd></div>`:''}<div><dt>${kind==='pace'?'Fastest sample':kind==='elevation'?'Highest point':'Maximum'}</dt><dd>${metricText(kind==='pace'?min:max,kind)} <small>${MEASURES[kind].unit}</small></dd></div></dl>${insight?`<p class="av-insight">${esc(insight)}</p>`:''}</div>`;
}
export function activityChartPanel(activity,state,c,chartSvg,distribution){
 const measures=Object.entries(MEASURES).filter(([key])=>activity.records.some(r=>metricValue(r,key)!==null)&&(keyAllowed(activity,key)));
 if(!measures.length)return `<section class="analysis-panel section"><h2>Run analysis</h2><p>Your saved screenshots include summaries and splits. Stream charts appear with a recorded activity.</p></section>`;
 const kind=state.series,axis=c?.axis||'time',splitContent=splitsMarkup(activity),headline=metricHeadline(activity,kind),title=/run/i.test(activity.sport)?'Run analysis':'Activity analysis';
 return `<section class="analysis-panel av-panel section av-${kind}" aria-labelledby="analysis-title"><div class="av-heading"><h2 id="analysis-title">${title}</h2>${splitContent?'<a href="#kilometre-splits">View splits</a>':''}</div><div class="series-tabs" role="group" aria-label="Chart measurement">${measures.map(([key,m])=>`<button data-series="${key}" aria-pressed="${kind===key}">${m.label}</button>`).join('')}</div><div class="av-toolbar"><div class="chart-readout"><span id="chart-time">${headline.label}</span><strong id="chart-value">${metricText(headline.value,kind)} ${MEASURES[kind].unit}</strong></div><div class="av-axis" role="group" aria-label="Chart horizontal axis"><button data-chart-axis="distance" aria-pressed="${axis==='distance'}" ${!distanceAxis(activity.records)?'disabled':''}>Distance</button><button data-chart-axis="time" aria-pressed="${axis==='time'}">Time</button></div></div><div class="chart-canvas" tabindex="0" role="slider" aria-label="Inspect ${MEASURES[kind].label.toLowerCase()} along the run" aria-valuemin="0" aria-valuemax="${activity.records.length-1}" aria-valuenow="${state.cursor??0}" aria-valuetext="${state.cursor===null?'Full session':visualTime(activity.records[state.cursor].t)}">${chartSvg}</div><div class="av-legend"><span><i></i>${MEASURES[kind].label}</span>${c?.terrain?`<span class="av-terrain-legend"><i></i>Terrain · ${Math.round(c.terrainMin)}–${Math.round(c.terrainMax)} m</span>`:''}</div><p class="av-help">Touch the chart to inspect. Arrow keys move through the run.</p>${metricSummary(activity,kind)}${kind==='pace'&&c?.focused?`<button type="button" class="text-button" data-action="chart-range" aria-pressed="${state.fullPaceRange}">Show full pace range · ${c.omitted} samples outside view</button>`:kind==='pace'&&state.fullPaceRange?'<button type="button" class="text-button" data-action="chart-range" aria-pressed="true">Focus typical pace range</button>':''}${distribution}${splitContent}${activityEffortsMarkup(activity)}<details class="av-method"><summary>Chart details</summary><p>Recorded samples over ${axis==='distance'?'distance':'elapsed time'}. Gaps over fifteen seconds stay open. Terrain uses an independent elevation scale. Exact values follow your selection on the map.</p></details></section>`;
}
const keyAllowed=(a,key)=>key!=='pace'||a.distance>=10;
export function splitsMarkup(activity){
 const rows=kilometreSplits(activity);if(!rows.length)return '';
 const paces=rows.map(r=>r.paceSPerKm).filter(Number.isFinite),best=paces.length?Math.min(...paces):null,max=paces.length?Math.max(...paces):null;
 return `<section class="av-splits" id="kilometre-splits" aria-labelledby="split-title"><div class="av-heading"><h2 id="split-title">Kilometre splits</h2><span>Elapsed pace /km</span></div><table><caption class="sr-only">Recorded kilometre splits with elapsed pace, elevation change and heart rate</caption><thead><tr><th scope="col">Km</th><th scope="col">Pace</th><th scope="col" class="av-split-bar-heading">Pace comparison</th><th scope="col">Elev.</th><th scope="col">HR</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.paceSPerKm===best?'av-fastest':''}"><th scope="row">${r.distanceM>=999?r.index:(r.distanceM/1000).toFixed(2)}</th><td>${visualTime(r.paceSPerKm)}</td><td class="av-bar-cell"><i style="width:${r.complete?35+(max===best?65:(max-r.paceSPerKm)/(max-best)*65):0}%" aria-hidden="true"></i>${r.paceSPerKm===best?'<span class="sr-only">Fastest split</span>':''}</td><td>${r.elevationChangeM===null?'—':(r.elevationChangeM>0?'+':'')+Math.round(r.elevationChangeM)}</td><td>${r.hrBpm===null?'—':Math.round(r.hrBpm)}</td></tr>`).join('')}</tbody></table><details class="av-method"><summary>Split details</summary><p>Exact kilometre boundaries interpolated from recorded distance and elapsed timestamps. Heart rate is time-weighted. A recording gap leaves that split unavailable. Final fragments under one hundred metres are omitted. Device laps remain separate below.</p></details></section>`;
}

const effortCache=new WeakMap();
export function activityEffortsMarkup(activity){
 let efforts=effortCache.get(activity);if(!efforts){efforts=bestEfforts(activity).filter(e=>[400,804.672,1000,1609.344,3218.688,5000].includes(e.distanceM));effortCache.set(activity,efforts);}if(!efforts.length)return '';
 const label=d=>d===804.672?'½ mile':d===1609.344?'1 mile':d===3218.688?'2 miles':d<1000?d+' m':d/1000+' km';
 return `<section class="av-results" aria-labelledby="run-results-title"><div class="av-heading"><h2 id="run-results-title">Best efforts in this run</h2><span>${efforts.length}</span></div><div class="av-effort-list">${efforts.map(e=>`<a href="/training?view=progress&benchmark=${e.distanceM}&effort=${encodeURIComponent(activity.id)}#pr-effort-title"><strong>${label(e.distanceM)}</strong><span>${visualTime(e.elapsedS)}<small>${visualTime(e.paceSPerKm)} /km</small></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a>`).join('')}</div><p>Fastest elapsed segments. Select a distance to compare your runs.</p></section>`;
}
